def notify_overdue_invoice_hold(description: str) -> dict[str, object]:
    """Return a recorded success-or-failure outcome after attempting the exact owner HOLD notification once."""
    import json
    import logging
    import urllib.error
    import urllib.request

    log = logging.getLogger(__name__)
    if not isinstance(description, str) or not description:
        raise ValueError("description must be a non-empty string")

    class NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, req, fp, code, msg, headers, newurl):
            return None

    message = "HOLD: " + description
    raw_body = json.dumps(
        {"message": message}, ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")
    request = urllib.request.Request(
        "http://127.0.0.1:18292/owner/notify",
        data=raw_body,
        headers={"Accept": "application/json", "Content-Type": "application/json"},
        method="POST",
    )
    opener = urllib.request.build_opener(NoRedirect)
    log.warning("SOFT_FAIL HOLD: %s", description)
    try:
        with opener.open(request, timeout=10) as response:
            status = response.getcode()
            response.read()
        if isinstance(status, bool) or not isinstance(status, int) or not 200 <= status <= 299:
            raise RuntimeError(f"POST /owner/notify returned non-success HTTP status {status!r}")
    except urllib.error.HTTPError as exc:
        detail = ""
        try:
            detail = exc.read(300).decode("utf-8", errors="replace")
        except Exception:
            pass
        suffix = f"; response {detail!r}" if detail else ""
        error = f"POST /owner/notify returned HTTP {exc.code}{suffix}"
        log.error("SOFT_FAIL owner HOLD notification failed: %s", error)
        return {"attempted": True, "succeeded": False, "error": error, "message": message}
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        error = f"POST /owner/notify failed without a definite success: {exc}"
        log.error("SOFT_FAIL owner HOLD notification failed: %s", error)
        return {"attempted": True, "succeeded": False, "error": error, "message": message}
    except Exception as exc:
        error = str(exc)
        log.error("SOFT_FAIL owner HOLD notification failed: %s", error)
        return {"attempted": True, "succeeded": False, "error": error, "message": message}
    log.info("PHASE owner HOLD notification succeeded HTTP=%s", status)
    return {"attempted": True, "succeeded": True, "http_status": status, "message": message}

