def post_validated_overdue_invoice_digest(week: int, invoice_count: int, total_amount_cents: int, reminders_sent: int) -> dict[str, object]:
    """Return definite 2xx success metadata after posting the exact five-key EUR invoice digest, or raise on ambiguity."""
    import json
    import logging
    import urllib.error
    import urllib.request

    log = logging.getLogger(__name__)
    values = {
        "week": week,
        "invoice_count": invoice_count,
        "total_amount_cents": total_amount_cents,
        "reminders_sent": reminders_sent,
    }
    for name, value in values.items():
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError(f"{name} must be a non-negative integer and not a boolean")
    if reminders_sent != invoice_count:
        raise ValueError("reminders_sent must equal invoice_count before the digest is posted")

    class NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, req, fp, code, msg, headers, newurl):
            return None

    digest = {
        "week": week,
        "invoice_count": invoice_count,
        "total_amount_cents": total_amount_cents,
        "reminders_sent": reminders_sent,
        "flagged_invoice_ids": [],
    }
    raw_body = json.dumps(digest, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    request = urllib.request.Request(
        "http://127.0.0.1:18292/report",
        data=raw_body,
        headers={"Accept": "application/json", "Content-Type": "application/json"},
        method="POST",
    )
    opener = urllib.request.build_opener(NoRedirect)
    log.info("PHASE post weekly digest")
    try:
        with opener.open(request, timeout=10) as response:
            status = response.getcode()
            response.read()
    except urllib.error.HTTPError as exc:
        detail = ""
        try:
            detail = exc.read(300).decode("utf-8", errors="replace")
        except Exception:
            pass
        suffix = f"; response {detail!r}" if detail else ""
        log.error("SOFT_FAIL weekly digest HTTP=%s", exc.code)
        raise RuntimeError(f"POST /report returned HTTP {exc.code}{suffix}") from exc
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        log.error("SOFT_FAIL weekly digest transport=%s", exc)
        raise RuntimeError(f"POST /report failed without a definite success: {exc}") from exc
    except Exception as exc:
        log.error("SOFT_FAIL weekly digest unexpected=%s", exc)
        raise RuntimeError(f"POST /report had an unexpected transport failure: {exc}") from exc
    if isinstance(status, bool) or not isinstance(status, int) or not 200 <= status <= 299:
        log.error("SOFT_FAIL weekly digest status=%r", status)
        raise RuntimeError(f"POST /report returned non-success HTTP status {status!r}")
    log.info("PHASE digest definitely succeeded HTTP=%s", status)
    return {"succeeded": True, "http_status": status, "digest": digest}

