def send_validated_overdue_invoice_reminder(contact_email: str, invoice_id: str) -> dict[str, object]:
    """Return definite 2xx success metadata after posting exactly one validated invoice reminder, or raise on ambiguity."""
    import json
    import logging
    import urllib.error
    import urllib.request

    log = logging.getLogger(__name__)
    if not isinstance(contact_email, str) or not contact_email:
        raise ValueError("contact_email must be a non-empty string")
    if not isinstance(invoice_id, str) or not invoice_id:
        raise ValueError("invoice_id must be a non-empty string")

    class NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, req, fp, code, msg, headers, newurl):
            return None

    body = {"to": contact_email, "invoice_id": invoice_id}
    raw_body = json.dumps(body, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    request = urllib.request.Request(
        "http://127.0.0.1:18292/remind",
        data=raw_body,
        headers={"Accept": "application/json", "Content-Type": "application/json"},
        method="POST",
    )
    opener = urllib.request.build_opener(NoRedirect)
    try:
        with opener.open(request, timeout=10) as response:
            status = response.getcode()
            response.read()
    except urllib.error.HTTPError as exc:
        detail = ""
        try:
            detail = exc.read(300).decode("utf-8", errors="replace")
        except Exception:
            pass
        suffix = f"; response {detail!r}" if detail else ""
        log.error("SOFT_FAIL reminder invoice_id=%r HTTP=%s", invoice_id, exc.code)
        raise RuntimeError(f"POST /remind returned HTTP {exc.code}{suffix}") from exc
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        log.error("SOFT_FAIL reminder invoice_id=%r transport=%s", invoice_id, exc)
        raise RuntimeError(f"POST /remind failed without a definite success: {exc}") from exc
    except Exception as exc:
        log.error("SOFT_FAIL reminder invoice_id=%r unexpected=%s", invoice_id, exc)
        raise RuntimeError(f"POST /remind had an unexpected transport failure: {exc}") from exc
    if isinstance(status, bool) or not isinstance(status, int) or not 200 <= status <= 299:
        log.error("SOFT_FAIL reminder invoice_id=%r status=%r", invoice_id, status)
        raise RuntimeError(f"POST /remind returned non-success HTTP status {status!r}")
    log.info("PHASE reminder definitely succeeded invoice_id=%r HTTP=%s", invoice_id, status)
    return {"succeeded": True, "http_status": status, "invoice_id": invoice_id}

