def load_weekly_overdue_invoice_batch() -> dict[str, object]:
    """Return a fully validated next-week invoice batch with exact integer-cent totals, or raise before any delivery effect."""
    import json
    import logging
    import urllib.error
    import urllib.request

    log = logging.getLogger(__name__)
    base = "http://127.0.0.1:18292"
    expected_fields = {
        "id", "vendor", "amount_cents", "currency", "days_overdue", "contact_email"
    }

    class NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, req, fp, code, msg, headers, newurl):
            return None

    class DuplicateKey(ValueError):
        pass

    opener = urllib.request.build_opener(NoRedirect)

    def get_bytes(path: str) -> bytes:
        request = urllib.request.Request(
            base + path,
            headers={"Accept": "application/json"},
            method="GET",
        )
        try:
            with opener.open(request, timeout=10) as response:
                status = response.getcode()
                raw = response.read()
        except urllib.error.HTTPError as exc:
            detail = ""
            try:
                detail = exc.read(300).decode("utf-8", errors="replace")
            except Exception:
                pass
            suffix = f"; response {detail!r}" if detail else ""
            raise RuntimeError(f"GET {path} returned HTTP {exc.code}{suffix}") from exc
        except (urllib.error.URLError, TimeoutError, OSError) as exc:
            raise RuntimeError(f"GET {path} failed without a definite success: {exc}") from exc
        except Exception as exc:
            raise RuntimeError(f"GET {path} had an unexpected transport failure: {exc}") from exc
        if isinstance(status, bool) or not isinstance(status, int) or not 200 <= status <= 299:
            raise RuntimeError(f"GET {path} returned non-success HTTP status {status!r}")
        return raw

    def parse_json(raw: bytes, context: str):
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise RuntimeError(f"{context} response was not valid UTF-8 JSON") from exc

        def reject_duplicates(pairs):
            obj = {}
            for key, value in pairs:
                if key in obj:
                    raise DuplicateKey(f"duplicate JSON key {key!r}")
                obj[key] = value
            return obj

        try:
            return json.loads(text, object_pairs_hook=reject_duplicates)
        except (json.JSONDecodeError, DuplicateKey) as exc:
            raise RuntimeError(f"{context} returned malformed or ambiguous JSON: {exc}") from exc

    log.info("PHASE fetch and validate last completed report")
    last_payload = parse_json(get_bytes("/reports/last"), "GET /reports/last")
    if not isinstance(last_payload, dict):
        raise RuntimeError(
            f"GET /reports/last JSON was {type(last_payload).__name__}, expected an object"
        )
    if set(last_payload) != {"last_week"}:
        raise RuntimeError(
            f"GET /reports/last object keys were {sorted(map(str, last_payload))!r}, expected exactly ['last_week']"
        )
    last_week = last_payload["last_week"]
    if isinstance(last_week, bool) or not isinstance(last_week, int) or last_week < 0:
        raise RuntimeError(
            f"last_week was {last_week!r}, expected a non-negative integer and not a boolean"
        )
    week = last_week + 1

    log.info("PHASE fetch invoice list for week %s", week)
    path = f"/invoices?week={week}"
    payload = parse_json(get_bytes(path), f"GET {path}")
    if not isinstance(payload, list):
        raise RuntimeError(f"GET /invoices JSON was {type(payload).__name__}, expected a list")

    seen_ids: set[str] = set()
    invoices: list[dict[str, object]] = []
    for index, item in enumerate(payload):
        label = f"invoice item {index}"
        if not isinstance(item, dict):
            raise RuntimeError(f"{label} was {type(item).__name__}, expected an object")
        actual_fields = set(item)
        if actual_fields != expected_fields:
            missing = sorted(expected_fields - actual_fields)
            extra = sorted(actual_fields - expected_fields, key=str)
            raise RuntimeError(
                f"{label} had invalid fields (missing={missing!r}, extra={extra!r})"
            )
        invoice_id = item["id"]
        if not isinstance(invoice_id, str) or not invoice_id:
            raise RuntimeError(f"{label} id was {invoice_id!r}, expected a non-empty string")
        if invoice_id in seen_ids:
            raise RuntimeError(
                f"duplicate invoice id {invoice_id!r} was present in the complete list"
            )
        if not isinstance(item["vendor"], str):
            raise RuntimeError(f"invoice {invoice_id!r} vendor was not a string")
        amount = item["amount_cents"]
        if isinstance(amount, bool) or not isinstance(amount, int) or amount < 0:
            raise RuntimeError(
                f"invoice {invoice_id!r} amount_cents was {amount!r}, expected a non-negative integer and not a boolean"
            )
        currency = item["currency"]
        if not isinstance(currency, str) or currency != "EUR":
            raise RuntimeError(
                f"invoice {invoice_id!r} currency was {currency!r}, expected exactly 'EUR'"
            )
        days = item["days_overdue"]
        if isinstance(days, bool) or not isinstance(days, int) or days < 0:
            raise RuntimeError(
                f"invoice {invoice_id!r} days_overdue was {days!r}, expected a non-negative integer and not a boolean"
            )
        email = item["contact_email"]
        if not isinstance(email, str) or not email:
            raise RuntimeError(
                f"invoice {invoice_id!r} contact_email was {email!r}, expected a non-empty string"
            )
        seen_ids.add(invoice_id)
        invoices.append(item)

    total = sum(int(invoice["amount_cents"]) for invoice in invoices)
    log.info(
        "PHASE complete invoice list validated week=%s count=%s total_amount_cents=%s",
        week,
        len(invoices),
        total,
    )
    return {
        "week": week,
        "invoices": invoices,
        "invoice_count": len(invoices),
        "total_amount_cents": total,
    }
